def manipulate_stock_prices(prices, operation='First'):
    """
    Manipulates the given list of stock prices based on the specified operation.

    Parameters:
        prices (list of float): A list of stock prices.
        operation (str): The operation to perform on the stock prices. It can be one of the following:
                         - 'First': Return the first price in the list.
                         - 'Max': Return the maximum price in the list.
                         - 'Min': Return the minimum price in the list.
                         - 'Average': Return the average of the prices in the list.
                         - 'Last': Return the last price in the list.

    Returns:
        float: The result of the specified operation on the stock prices.
    """
    if not prices:
        raise ValueError("The prices list is empty.")

    if operation == 'First':
        return prices[0]
    elif operation == 'Max':
        return max(prices)
    elif operation == 'Min':
        return min(prices)
    elif operation == 'Average':
        return sum(prices) / len(prices)
    elif operation == 'Last':
        return prices[-1]
    else:
        raise ValueError(f"Unknown operation: {operation}")

# Example usage:
